//! The key-name table: the single source of truth mapping friendly key names
//! (lowercase evdev names without the `KEY_` prefix: `a`, `f5`, `leftctrl`,
//! `kp1`, ...) to evdev codes, uinput events, Windows scancodes, and back.
//! See DESIGN.md §"Key naming".
//!
//! The table is generated by the [`keys!`] macro so that a name, its key code,
//! its `uinput-tokio` event variant and its Windows encoding can never drift
//! apart: adding a key means adding exactly one row.
//!
//! **Key codes are the crate's own currency.** The identifier in each row —
//! `KEY_A`, `KEY_LEFTCTRL` — names the evdev constant the literal beside it is
//! taken from, but the literal is what the table actually carries, because the
//! `evdev` crate is a Linux-only dependency and this table has to compile
//! everywhere. A `#[cfg(target_os = "linux")]` test asserts every literal
//! against its `evdev::KeyCode::KEY_*` constant, which is the compile-time
//! guarantee the constants used to give.
//!
//! **The Windows column** encodes each key the way `SendInput` wants it (see
//! [`WinKey`]). Three facts shape it:
//!
//! 1. evdev key codes `1..=88` are numerically identical to AT set-1
//!    scancodes (`KEY_ESC` = 1 = `0x01`, `KEY_A` = 30 = `0x1E`, `KEY_SPACE` =
//!    57 = `0x39`, `KEY_F12` = 88 = `0x58`), so those rows repeat their own
//!    code in hexadecimal.
//! 2. Everything above that is an `E0`-prefixed ("extended") scancode written
//!    `win_ext(...)`, or — for `F13`..`F24` — the non-extended `0x64`..`0x6F`
//!    block.
//! 3. `pause` cannot be expressed as a scancode at all: the keyboard sends it
//!    as the `E1 1D 45` sequence, which `SendInput`'s single-scancode field
//!    cannot carry. It is the one row injected by virtual key instead
//!    (`win_vk(VK_PAUSE)`).

#[cfg(target_os = "linux")]
use uinput_tokio::event::keyboard::{
    Key as UKey, KeyPad as UKeyPad, Keyboard as UKeyboard, Misc as UMisc,
};

/// A raw evdev key code.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct KeyCode(pub u16);

impl KeyCode {
    /// The raw evdev code carried by this key.
    pub const fn code(self) -> u16 {
        self.0
    }
}

impl std::fmt::Display for KeyCode {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match name(*self) {
            Some(name) => f.write_str(name),
            None => write!(f, "<unnamed key {}>", self.0),
        }
    }
}

/// How a key has to be handed to the Windows `SendInput` API.
///
/// Scancodes are preferred over virtual keys throughout: a game reading raw
/// input (which is most of them) sees a scancode where it would ignore a
/// synthesized virtual key, and a scancode is layout-independent — `w` is the
/// key above `s` on an AZERTY keyboard too, which is what a movement macro
/// means.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WinKey {
    /// A plain AT set-1 scancode: `KEYEVENTF_SCANCODE` with `wScan` set to it.
    Scan(u16),
    /// An `E0`-prefixed scancode — the second byte of the pair — which
    /// additionally needs `KEYEVENTF_EXTENDEDKEY`.
    ScanExt(u16),
    /// A virtual-key code, for the one key (`pause`) whose scancode is a
    /// multi-byte `E1` sequence `SendInput` cannot express.
    VirtualKey(u16),
}

/// Resolves the `uinput-tokio` event for one table row.
///
/// `uinput-tokio` splits the keyboard key space across several enums, so the
/// table names the family (`key`, `pad`, `misc`) alongside the variant. A row
/// whose key has no variant in the crate at all is written `none`; such keys
/// fall back to raw `EV_KEY` writes in [`crate::output::uinput`], and cannot be
/// registered as a device capability.
#[cfg(target_os = "linux")]
macro_rules! uinput_event {
    (key $variant:ident) => {
        Some(UKeyboard::Key(UKey::$variant))
    };
    (pad $variant:ident) => {
        Some(UKeyboard::KeyPad(UKeyPad::$variant))
    };
    (misc $variant:ident) => {
        Some(UKeyboard::Misc(UMisc::$variant))
    };
    (none) => {
        None
    };
}

/// Resolves the [`WinKey`] for one table row's third column.
macro_rules! win_key {
    (win, $scan:literal) => {
        WinKey::Scan($scan)
    };
    (win_ext, $scan:literal) => {
        WinKey::ScanExt($scan)
    };
    (win_vk, $vk:literal) => {
        WinKey::VirtualKey($vk)
    };
}

/// Generates the whole key table from a list of
/// `"name" => EVDEV_CONSTANT = <code> / <family> <UinputVariant> / <windows>`
/// rows.
macro_rules! keys {
    ($($name:literal => $evdev:ident = $code:literal
        / $family:ident $($variant:ident)?
        / $win:ident($scan:literal)),* $(,)?) => {
        /// Every friendly key name, in table order.
        const NAMES: &[&str] = &[$($name),*];

        /// Every key code in the table, in table order.
        const CODES: &[KeyCode] = &[$(KeyCode($code)),*];

        /// Every row's name, code and `evdev` constant, for the test which
        /// pins the literals above against the kernel's own numbering.
        #[cfg(all(test, target_os = "linux"))]
        const EVDEV_ROWS: &[(&str, u16, evdev::KeyCode)] =
            &[$(($name, $code, evdev::KeyCode::$evdev)),*];

        /// Looks up a key by its friendly name (`"leftctrl"`, `"f5"`, `"kp1"`).
        ///
        /// Returns `None` for names which are not in the table; callers should
        /// pair that with [`suggest`] to produce a "did you mean" hint.
        pub fn from_name(name: &str) -> Option<KeyCode> {
            match name {
                $($name => Some(KeyCode($code)),)*
                _ => None,
            }
        }

        /// The friendly name for a key code, if it is one we know about.
        pub fn name(code: KeyCode) -> Option<&'static str> {
            match code.0 {
                $($code => Some($name),)*
                _ => None,
            }
        }

        /// The `uinput-tokio` event for a key, where the crate models it.
        ///
        /// `None` means `uinput-tokio` has no variant for this code; the device
        /// wrapper falls back to writing the raw `EV_KEY` code instead.
        #[cfg(target_os = "linux")]
        pub fn to_uinput(code: KeyCode) -> Option<UKeyboard> {
            match code.0 {
                $($code => uinput_event!($family $($variant)?),)*
                _ => None,
            }
        }

        /// How to hand a key to Windows' `SendInput`, for keys in the table.
        ///
        /// Kept compiled on every platform — it is pure data, and a table only
        /// Windows could see would be a table only Windows could test.
        pub fn to_windows(code: KeyCode) -> Option<WinKey> {
            match code.0 {
                $($code => Some(win_key!($win, $scan)),)*
                _ => None,
            }
        }
    };
}

