/// The evdev key code for a key, used when matching hotkey events read from
/// `/dev/input/event*`.
#[cfg(target_os = "linux")]
pub fn to_evdev(code: KeyCode) -> evdev::KeyCode {
    evdev::KeyCode(code.0)
}

/// Every friendly key name we accept, in table order.
///
/// Used by the key reference documentation and by [`suggest`].
pub fn all_names() -> &'static [&'static str] {
    NAMES
}

/// Every key code in the table, in table order.
///
/// The uinput device registers all of these as capabilities so that it looks
/// like a real keyboard to SDL and games (DESIGN.md §"`run` assembly").
pub fn all_codes() -> &'static [KeyCode] {
    CODES
}

/// The largest edit distance we will still call a typo.
const MAX_SUGGESTION_DISTANCE: usize = 2;

/// A `strsim`-ranked "did you mean ...?" suggestion for an unknown key name.
///
/// Candidates within [`MAX_SUGGESTION_DISTANCE`] edits are ranked by distance,
/// then by whether they share the misspelling's first letter (typos rarely
/// change it), then by how close their length is, and finally alphabetically so
/// the result is deterministic.
///
/// A candidate must also differ by fewer edits than the shorter of the two
/// names is long, which is what stops short nonsense from matching short keys —
/// `"zzz"` is two edits from `"z"`, but nobody meant `"z"`.
pub fn suggest(name: &str) -> Option<&'static str> {
    let name = name.trim().to_ascii_lowercase();
    if name.is_empty() {
        return None;
    }

    let first = name.chars().next();

    all_names()
        .iter()
        .copied()
        .filter_map(|candidate| {
            let distance = strsim::levenshtein(&name, candidate);
            let plausible =
                distance <= MAX_SUGGESTION_DISTANCE && distance < name.len().min(candidate.len());
            plausible.then_some((distance, candidate))
        })
        .min_by_key(|(distance, candidate)| {
            (
                *distance,
                // `false` sorts first, so a shared first letter wins ties.
                candidate.chars().next() != first,
                candidate.len().abs_diff(name.len()),
                *candidate,
            )
        })
        .map(|(_, candidate)| candidate)
}

#[cfg(test)]
mod tests {
    use super::*;
    use rstest::rstest;

    #[test]
    fn every_name_round_trips() {
        for &name in all_names() {
            let code = from_name(name).unwrap_or_else(|| panic!("'{name}' is not resolvable"));
            let back = super::name(code).unwrap_or_else(|| panic!("{code:?} has no name"));
            assert_eq!(back, name, "'{name}' did not round-trip");
            assert_eq!(
                from_name(back),
                Some(code),
                "'{name}' did not round-trip back to the same code"
            );
        }
    }

    #[test]
    fn names_and_codes_are_unique_and_aligned() {
        assert_eq!(all_names().len(), all_codes().len());

        let names: std::collections::HashSet<_> = all_names().iter().collect();
        assert_eq!(
            names.len(),
            all_names().len(),
            "duplicate key name in table"
        );

        let codes: std::collections::HashSet<_> = all_codes().iter().collect();
        assert_eq!(
            codes.len(),
            all_codes().len(),
            "duplicate key code in table"
        );

        for (&name, &code) in all_names().iter().zip(all_codes()) {
            assert_eq!(from_name(name), Some(code), "'{name}' is misaligned");
        }
    }

    /// The safety net for the literal codes in the table.
    ///
    /// The macro used to build every row out of an `evdev::KeyCode::KEY_*`
    /// constant, which made a wrong number impossible; the table now carries
    /// the number itself so that it compiles on Windows too, and this test is
    /// what replaces that guarantee. A row whose literal drifts away from the
    /// kernel's numbering fails here, naming the key.
    #[cfg(target_os = "linux")]
    #[test]
    fn every_code_matches_the_evdev_constant() {
        for &(name, code, expected) in EVDEV_ROWS {
            assert_eq!(
                code, expected.0,
                "'{name}' claims evdev code {code}, but evdev says {}",
                expected.0
            );
        }
        assert_eq!(EVDEV_ROWS.len(), all_names().len());
    }

    /// Every key we can be asked to press must be expressible to `SendInput`,
    /// or a profile using it would fail at runtime on Windows with nothing to
    /// say about which key. Compiled everywhere: the table is pure data, so
    /// Linux CI is where this gap gets caught.
    #[test]
    fn every_name_has_a_windows_encoding() {
        let missing: Vec<_> = all_names()
            .iter()
            .filter(|name| to_windows(from_name(name).unwrap()).is_none())
            .collect();
        assert!(missing.is_empty(), "no windows encoding for: {missing:?}");
    }

    /// The three shapes of the Windows column, spot-checked against the AT
    /// set-1 table: the `1..=88` identity range, the `E0` extended set, the
    /// `F13`..`F24` block, and the one virtual-key row.
    #[rstest]
    #[case("esc", WinKey::Scan(0x01))]
    #[case("a", WinKey::Scan(0x1E))]
    #[case("w", WinKey::Scan(0x11))]
    #[case("space", WinKey::Scan(0x39))]
    #[case("f1", WinKey::Scan(0x3B))]
    #[case("f12", WinKey::Scan(0x58))]
    #[case("leftctrl", WinKey::Scan(0x1D))]
    #[case("leftalt", WinKey::Scan(0x38))]
    #[case("kp1", WinKey::Scan(0x4F))]
    #[case("kpasterisk", WinKey::Scan(0x37))]
    #[case("numlock", WinKey::Scan(0x45))]
    #[case("scrolllock", WinKey::Scan(0x46))]
    #[case("f13", WinKey::Scan(0x64))]
    #[case("f24", WinKey::Scan(0x6F))]
    #[case("rightctrl", WinKey::ScanExt(0x1D))]
    #[case("rightalt", WinKey::ScanExt(0x38))]
    #[case("leftmeta", WinKey::ScanExt(0x5B))]
    #[case("rightmeta", WinKey::ScanExt(0x5C))]
    #[case("up", WinKey::ScanExt(0x48))]
    #[case("down", WinKey::ScanExt(0x50))]
    #[case("left", WinKey::ScanExt(0x4B))]
    #[case("right", WinKey::ScanExt(0x4D))]
    #[case("home", WinKey::ScanExt(0x47))]
    #[case("end", WinKey::ScanExt(0x4F))]
    #[case("pageup", WinKey::ScanExt(0x49))]
    #[case("pagedown", WinKey::ScanExt(0x51))]
    #[case("insert", WinKey::ScanExt(0x52))]
    #[case("delete", WinKey::ScanExt(0x53))]
    #[case("kpenter", WinKey::ScanExt(0x1C))]
    #[case("kpslash", WinKey::ScanExt(0x35))]
    #[case("sysrq", WinKey::ScanExt(0x37))]
    #[case("mute", WinKey::ScanExt(0x20))]
    #[case("volumedown", WinKey::ScanExt(0x2E))]
    #[case("volumeup", WinKey::ScanExt(0x30))]
    #[case("nextsong", WinKey::ScanExt(0x19))]
    #[case("playpause", WinKey::ScanExt(0x22))]
    #[case("previoussong", WinKey::ScanExt(0x10))]
    // The E1 1D 45 sequence has no single-scancode form, so this one row is
    // injected by virtual key (VK_PAUSE).
    #[case("pause", WinKey::VirtualKey(0x13))]
    fn windows_encodings_are_the_at_set_1_ones(#[case] name: &str, #[case] expected: WinKey) {
        assert_eq!(
            to_windows(from_name(name).expect("known key")),
            Some(expected)
        );
    }

    /// Everything the kernel numbers at or below 88 is its own AT set-1
    /// scancode, which is the rule the table's first column is written to.
    /// Above that, nothing may claim the identity by accident.
    #[test]
    fn the_identity_range_is_exactly_the_low_codes() {
        for &code in all_codes() {
            let win = to_windows(code).expect("every key has a windows encoding");
            if code.0 <= 88 {
                assert_eq!(
                    win,
                    WinKey::Scan(code.0),
                    "'{code}' is in the identity range but does not map to its own code"
                );
            } else {
                assert_ne!(
                    win,
                    WinKey::Scan(code.0),
                    "'{code}' is above the identity range and must not reuse its own code"
                );
            }
        }
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn every_name_has_a_uinput_event() {
        // DESIGN.md §Risks 7: verify uinput-tokio covers the whole table. Any
        // key which is not covered can still be written as a raw EV_KEY code,
        // but cannot be registered as a device capability, so a gap here is
        // worth knowing about.
        let missing: Vec<_> = all_names()
            .iter()
            .filter(|name| to_uinput(from_name(name).unwrap()).is_none())
            .collect();
        assert!(missing.is_empty(), "no uinput event for: {missing:?}");
    }

    #[cfg(target_os = "linux")]
    #[rstest]
    #[case("a", evdev::KeyCode::KEY_A)]
    #[case("z", evdev::KeyCode::KEY_Z)]
    #[case("0", evdev::KeyCode::KEY_0)]
    #[case("9", evdev::KeyCode::KEY_9)]
    #[case("f5", evdev::KeyCode::KEY_F5)]
    #[case("f24", evdev::KeyCode::KEY_F24)]
    #[case("leftctrl", evdev::KeyCode::KEY_LEFTCTRL)]
    #[case("rightmeta", evdev::KeyCode::KEY_RIGHTMETA)]
    #[case("space", evdev::KeyCode::KEY_SPACE)]
    #[case("kp1", evdev::KeyCode::KEY_KP1)]
    #[case("kpasterisk", evdev::KeyCode::KEY_KPASTERISK)]
    #[case("pause", evdev::KeyCode::KEY_PAUSE)]
    #[case("playpause", evdev::KeyCode::KEY_PLAYPAUSE)]
    #[case("previoussong", evdev::KeyCode::KEY_PREVIOUSSONG)]
    fn to_evdev_agrees_with_evdev(#[case] name: &str, #[case] expected: evdev::KeyCode) {
        let code = from_name(name).expect("known key");
        assert_eq!(to_evdev(code), expected);
        assert_eq!(code.code(), expected.0);
    }

    #[test]
    fn unknown_names_do_not_resolve() {
        assert_eq!(from_name("leftcontrol"), None);
        assert_eq!(from_name("LEFTCTRL"), None);
        assert_eq!(from_name(""), None);
        assert_eq!(name(KeyCode(60000)), None);
    }

    #[rstest]
    #[case("leftctl", "leftctrl")]
    #[case("lefctrl", "leftctrl")]
    #[case("leftctrll", "leftctrl")]
    #[case("LeftCtrl", "leftctrl")]
    #[case("esk", "esc")]
    #[case("spce", "space")]
    #[case("entre", "enter")]
    #[case("bakspace", "backspace")]
    #[case("pgup", "pageup")]
    #[case("kpplu", "kpplus")]
    #[case("volumup", "volumeup")]
    fn suggest_finds_realistic_typos(#[case] typo: &str, #[case] expected: &str) {
        assert_eq!(suggest(typo), Some(expected), "suggestion for '{typo}'");
    }

    #[rstest]
    #[case("zzz")]
    #[case("zz")]
    #[case("")]
    #[case("supercalifragilistic")]
    #[case("mouse_wheel_up")]
    fn suggest_gives_up_on_nonsense(#[case] input: &str) {
        assert_eq!(suggest(input), None, "unexpected suggestion for '{input}'");
    }

    #[test]
    fn display_names_known_keys() {
        assert_eq!(from_name("leftctrl").unwrap().to_string(), "leftctrl");
        assert_eq!(KeyCode(60000).to_string(), "<unnamed key 60000>");
    }
}
